const examples=['Βοιώτιος','Στράτιος','Μαδύτιος','Σαββάτιος','Συβότιος','Φοίτιος','Ἐλεύτιος','Πευκέτιος','Αἰπύτιος','Ἀκύτιος','Βρέττιος','Βρούττιος','πλησίος','ἀντίος','Σκοτίος','Κλυτίος','Φρασίος','νήϊος','δήϊος','γήϊος','Τήϊος','Κήϊος','βασιλήϊος','Ἰλιήϊος','χαλκήϊος','Ὀδυσσήϊος','ἀρχήϊος','Παταρήϊος','Πυθήϊος','Αἰολήϊος','Μινυήϊος','πολεμήϊος','ποιμνήϊος','ταφήϊος','Κῷος','Κώϊος','Μινῷος','Μινώϊος','πατρώϊος','ἡρώϊος','Τρώϊος','Λητώϊος','Ὁμολώϊος','ἤπιος','Ἀλμώπιος','Συώπιος','δέϊος','Νυσήϊον'];
const key=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ς/g,'σ').trim();
function unaccent(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,m=>m==='\u0308'?m:'').normalize('NFC');}
function nuclei(word){
 const chars=Array.from(word.normalize('NFD').toLowerCase()).reduce((a,ch)=>{if(/[\u0300-\u036f]/.test(ch)){if(a.length)a[a.length-1].marks+=ch;}else a.push({ch,marks:''});return a;},[]);
 const out=[];const pairs=new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου']);
 for(let i=0;i<chars.length;i++){
  const a=chars[i];if(!'αεηιουω'.includes(a.ch))continue;
  const z=chars[i+1];let marks=a.marks;
  if(z&&pairs.has(a.ch+z.ch)&&!z.marks.includes('\u0308')&&!/[\u0300\u0301\u0342]/.test(a.marks)){marks+=z.marks;i++;}
  out.push({accent:/[\u0300\u0301\u0342]/.test(marks)});
 }
 return out;
}
function analyze(){
 const w=$('#inp').value.trim();
 if(!w){$('#result').textContent='—';$('#transform').textContent='—';delete $('#result').dataset.tag;return;}
 const norm=key(w), ns=nuclei(w), at=ns.findIndex(n=>n.accent), place=at<0?'(no accent mark found)':({1:'ultima',2:'penult',3:'antepenult'}[ns.length-at]||(ns.length-at)+'th from end');
 const known=examples.some(ex=>key(ex)===norm), pure=/(η|ω)ιοσ$/.test(norm), bary=['ηπιοσ','αλμωπιοσ','συωπιοσ'].includes(norm);
 let tag='?', rule='No passage classification assigned to this input.';
 if(norm===key('Νυσήϊον')){tag='AMBIGUOUS';rule='Two possible derivations: from Νύσιον with added η, or from Νῦσα by resolution and lengthening; the passage does not choose.';}
 else if(['πλησιοσ','αντιοσ'].includes(norm)){tag='NOTED';rule='Separately noted in the passage; do not extend a blanket accent rule to this form.';}
 else if(known&&pure){tag='PURE';rule='Pure -ιος with η/ω before ι: the passage specifies antepenult accent.';if(norm===key('Ὁμολώϊος'))rule+=' Its ω is attributed to pleonasm, not to resolution.';}
 else if(bary){tag='BARYTONE';rule='A cited non-pure form with η/ω: barytone means not accented on the last syllable.';}
 else if(known)rule='A cited example outside the specific pure/non-pure η/ω comparison.';
 $('#result').textContent=[`Input: ${w}`,`Syllables (approximate): ${ns.length}`,`Classification: ${tag}`,`Passage note: ${rule}`,`Accent detected: ${place}`].join('\n');$('#result').dataset.tag=tag;
 const tr=pair(w);$('#transform').textContent='Attested comparison: '+tr.out+'\n'+tr.note;
}
function pair(w){
 const pairs=[['Κῷος','Κώϊος','Resolution of the form in -ῳος.'],['Μινῷος','Μινώϊος','Resolution of the form in -ῳος.'],['δέϊος','δήϊος','The passage includes lengthening of ε to η in this comparison.']];
 const p=pairs.find(p=>key(p[0])===key(w));
 if(p)return{out:p[1],note:p[2]};
 const expanded=pairs.find(p=>key(p[1])===key(w));
 if(expanded)return{out:w,note:'Already the displayed expanded form; no additional change. '+expanded[2]};
 return{out:w,note:'No explicit transformation pair in this passage for this input.'};
}
examples.forEach(ex=>{const b=document.createElement('button');b.type='button';b.className='chip gr';b.textContent=ex;b.addEventListener('click',()=>{$('#inp').value=ex;analyze();});$('#chips').append(b);});
$('#btnAnalyze').addEventListener('click',analyze);
$('#btnClear').addEventListener('click',()=>{$('#inp').value='';analyze();$('#inp').focus();});
$('#btnRandom').addEventListener('click',()=>{$('#inp').value=examples[Math.floor(Math.random()*examples.length)];analyze();});
$('#btnResolve').addEventListener('click',()=>{if($('#inp').value.trim()){$('#inp').value=pair($('#inp').value.trim()).out;analyze();}});
$('#btnStrip').addEventListener('click',()=>{$('#inp').value=unaccent($('#inp').value);analyze();});
$('#inp').addEventListener('input',analyze);$('#inp').addEventListener('keydown',e=>{if(e.key==='Enter')analyze();});analyze();

