.result{font-family:var(--mono);white-space:pre-wrap;background:rgba(0,0,0,.18);border:1px dashed rgba(255,255,255,.16);border-radius:12px;padding:10px;min-height:86px}
.transform{font-family:var(--mono);white-space:pre-wrap;background:rgba(0,0,0,.18);border:1px dashed rgba(255,255,255,.16);border-radius:12px;padding:10px;min-height:64px;margin-top:10px}
.small{margin:0;color:var(--faint);font-size:13px}
.legend{margin:8px 0 0;padding-left:18px;color:var(--muted)}
.tag{display:inline-block;font-size:12px;padding:2px 8px;border-radius:999px;border:1px solid rgba(255,255,255,.18);margin-right:6px;vertical-align:1px}
.tag.pure{background:rgba(134,239,172,.14);border-color:rgba(134,239,172,.35)}
.tag.bary{background:rgba(251,113,133,.12);border-color:rgba(251,113,133,.35)}
.tag.warn{background:rgba(251,191,36,.12);border-color:rgba(251,191,36,.35)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.chip{border:1px solid var(--line);background:rgba(255,255,255,.06);padding:7px 10px;border-radius:999px;cursor:pointer;font-family:var(--gr,inherit)}
.chip:hover{background:rgba(255,255,255,.10)}
.ftr{margin-top:10px;color:var(--faint)}

