const $ = (sel) => document.querySelector(sel);

const examples = [
  "Βοιώτιος","Στράτιος","Μαδύτιος","Σαββάτιος","Συβότιος","Φοΐτιος",
  "Ἐλεύτιος","Πευκέτιος","Αἰπύτιος","Ἀκύτιος","Βρέττιος","Βρούττιος",
  "πλησίος","ἀντίος","Σκοτίος","Κλυτίος","Φρασίος",
  "νήϊος","δήϊος","γήϊος","Τήϊος","Κήϊος","βασιλήϊος","Ἰλιήϊος","χαλκήϊος","Ὀδυσσήϊος","ἀρχήϊος",
  "Παταρήϊος","Πυθήϊος","Αἰολήϊος","Μινυήϊος","πολεμήϊος","ποιμνήϊος","ταφήϊος",
  "Κῷος","Κώϊος","Μινῷος","Μινώϊος","πατρώϊος","ἡρώϊος","Τρώϊος","Λητώϊος",
  "Ὁμολώϊος","ἤπιος","Ἀλμώπιος","Συώπιος"
];

// --- Greek helpers (toy-level) ---
const combiningMarks = /[\u0300-\u036f]/g;

function nfd(s){ return (s||"").normalize('NFD'); }
function stripCombining(s){ return nfd(s).replace(combiningMarks,'').normalize('NFC'); }

// Remove Greek accent marks but keep diaeresis (¨) if present.
function stripAccentsKeepDiaeresis(s){
  const d = nfd(s);
  // remove tonos/oxia/varia/perispomeni, breathings, iota subscript, etc.
  // keep diaeresis U+0308
  const removed = d.replace(/[\u0300\u0301\u0302\u0303\u0304\u0306\u0307\u0309\u030A\u030B\u030C\u030D\u030E\u0310\u0311\u0313\u0314\u0315\u031A\u0342\u0343\u0344\u0345\u0346\u0347\u0348\u0349\u034A\u034B\u034C\u034D\u034E\u034F\u0350\u0351\u0352\u0353\u0354\u0355\u0356\u0357\u0358\u0359\u035A\u035B\u035C\u035D\u035E\u035F\u0360\u0361\u0362\u0363\u0364\u0365\u0366\u0367\u0368\u0369\u036A\u036B\u036C\u036D\u036E\u036F]/g, (m)=> m==='\u0308'?m:'');
  // The above nukes everything; re-add diaeresis by preserving it before removal.
  // Simpler: do a second pass that restores diaeresis from original.
  // We'll instead implement properly:
}

function stripAccentsKeepDiaeresis2(s){
  const d = nfd(s);
  let out = '';
  for (let i=0;i<d.length;i++){
    const ch = d[i];
    const code = ch.codePointAt(0);
    if (code>=0x0300 && code<=0x036F){
      if (code===0x0308) out += ch; // keep diaeresis
      // else drop
    } else out += ch;
  }
  return out.normalize('NFC');
}

const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function isVowel(ch){ return VOWELS.has(ch); }

function roughSyllables(word){
  // Very rough: count vowel groups in accent-stripped string.
  const s = stripAccentsKeepDiaeresis2(word);
  let count = 0;
  let inV = false;
  for (let i=0;i<s.length;i++){
    const ch = s[i];
    const v = isVowel(ch);
    if (v && !inV){ count++; inV = true; }
    if (!v) inV = false;
  }
  return count;
}

function endsWithIos(word){
  const s = stripAccentsKeepDiaeresis2(word);
  return /ιος$/i.test(s) || /ϊος$/i.test(s);
}

function isPureEtaOmegaBeforeI(word){
  // “pure” here: penult vowel looks like η/ω immediately before iota of -ios.
  // We check for ηι/ωι or ηϊ/ωϊ near the end.
  const s = stripAccentsKeepDiaeresis2(word);
  // normalize final -ios variants
  return /(η[ϊι]ος|ω[ϊι]ος)$/i.test(s);
}

function findAccentType(word){
  // detect if any accent mark exists and where (last 3 syllables only, toy)
  const d = nfd(word);
  // locate accented vowel index (first accent mark occurrence)
  let accentPos = -1;
  for (let i=0;i<d.length;i++){
    const code = d.codePointAt(i);
    if (code===0x0301 || code===0x0300 || code===0x0342){ // acute, grave, circumflex
      accentPos = i;
      break;
    }
  }
  if (accentPos<0) return {has:false, label:"(no accent mark found)"};

  // Map accent position to syllable index by counting vowel groups up to that point.
  const base = stripAccentsKeepDiaeresis2(word);
  // Need to align indices between NFD and NFC; approximate by stripping combining and using NFD scan.
  // We'll compute syllable count in NFD up to accentPos.
  let syll = 0;
  let inV = false;
  for (let i=0;i<accentPos;i++){
    const ch = d[i];
    if (!ch) continue;
    const code = ch.codePointAt(0);
    if (code>=0x0300 && code<=0x036F) continue;
    const v = isVowel(ch);
    if (v && !inV){ syll++; inV=true; }
    if (!v) inV=false;
  }
  const total = roughSyllables(word);
  const fromEnd = total - syll + 1; // 1=ultima,2=penult,3=antepenult...
  let place = "?";
  if (fromEnd===1) place = "ultima";
  else if (fromEnd===2) place = "penult";
  else if (fromEnd===3) place = "antepenult";
  else place = `${fromEnd}th from end`;
  return {has:true, label:place, total};
}

function suggestAccent(word){
  const s = stripAccentsKeepDiaeresis2(word);
  const okEnding = endsWithIos(s);
  const syl = roughSyllables(s);
  const pure = isPureEtaOmegaBeforeI(s);

  let tag = "?";
  let rule = "";
  let suggestion = "";

  if (!okEnding){
    tag = "?";
    rule = "Doesn’t look like it ends in -ιος/-ϊος (toy check).";
  } else if (syl < 3){
    tag = "?";
    rule = "Too few syllables for an antepenult accent (needs ≥3).";
  } else if (pure){
    tag = "PURE";
    rule = "‘Pure’ -ιος: η/ω before ι → often προπαροξύτονον (antepenult).";
    suggestion = "Try accent on the antepenult (…´…ιος).";
  } else {
    tag = "BARYTONE";
    rule = "Not ‘pure’ by η/ω-before-ι; Herodian says such -ιος forms often βαρυνεται.";
    suggestion = "Try a non-oxytone accent (often penult/antepenult).";
  }

  return {s, okEnding, syl, pure, tag, rule, suggestion};
}

function resolveToy(word){
  // playful: if ends with -ιος and has η/ω right before it, insert diaeresis on iota: ηιος->ήϊος (keeping existing accents)
  // We do it accent-stripped then return.
  const raw = word.trim();
  if (!raw) return {out:"", note:""};
  const s = stripAccentsKeepDiaeresis2(raw);

  // If already has -ϊος, do nothing.
  if (/ϊος$/i.test(s)) return {out: raw, note:"Already looks like -ϊος."};

  // If ends -ιος and has η/ω before iota, insert diaeresis.
  if (/(η|ω)ιος$/i.test(s)){
    const out = s.replace(/(η|ω)ιος$/i, (m, v)=> `${v}ϊος`);
    return {out, note:"Inserted diaeresis on ι (toy ‘resolution’)."};
  }

  // If ends -ῳος or -ῃος (rare in input), convert to -ώϊος/-ήϊος toyishly.
  if (/ῳος$/i.test(raw)){
    const base = stripAccentsKeepDiaeresis2(raw);
    const out = base.replace(/ωος$/i, 'ώϊος');
    return {out, note:"Toy: -ῳος → -ώϊος."};
  }
  if (/ῃος$/i.test(raw)){
    const base = stripAccentsKeepDiaeresis2(raw);
    const out = base.replace(/ηος$/i, 'ήϊος');
    return {out, note:"Toy: -ῃος → -ήϊος."};
  }

  return {out: raw, note:"No obvious place to insert -ϊ- near the end."};
}

function render(){
  const w = $('#inp').value.trim();
  if (!w){
    $('#result').textContent = '—';
    $('#transform').textContent = '—';
    return;
  }

  const sug = suggestAccent(w);
  const acc = findAccentType(w);

  const lines = [];
  lines.push(`Input: ${w}`);
  lines.push(`Ends in -ιος/-ϊος? ${sug.okEnding ? 'yes' : 'no'}`);
  lines.push(`Rough syllables: ${sug.syl}`);
  lines.push(`“Pure” (η/ω before ι)? ${sug.pure ? 'yes' : 'no'}`);
  lines.push(`Classification: ${sug.tag}`);
  lines.push(`Rule-of-thumb: ${sug.rule}`);
  if (sug.suggestion) lines.push(`Suggestion: ${sug.suggestion}`);
  lines.push('');
  lines.push(`Accent detected: ${acc.has ? acc.label : acc.label}`);

  $('#result').textContent = lines.join('\n');

  const tr = resolveToy(w);
  const tlines = [];
  tlines.push(`Resolution toy: ${tr.out || '—'}`);
  if (tr.note) tlines.push(`Note: ${tr.note}`);
  $('#transform').textContent = tlines.join('\n');

  // tag styling
  $('#result').dataset.tag = sug.tag;
}

function buildChips(){
  const box = $('#chips');
  box.innerHTML = '';
  examples.forEach(ex => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip gr';
    b.textContent = ex;
    b.addEventListener('click', () => { $('#inp').value = ex; render(); });
    box.appendChild(b);
  });
}

$('#btnAnalyze').addEventListener('click', render);
$('#btnClear').addEventListener('click', () => { $('#inp').value=''; render(); $('#inp').focus(); });
$('#btnRandom').addEventListener('click', () => {
  const ex = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = ex;
  render();
});
$('#btnResolve').addEventListener('click', () => {
  const w = $('#inp').value.trim();
  if (!w) return;
  const tr = resolveToy(w);
  $('#inp').value = tr.out;
  render();
});
$('#btnStrip').addEventListener('click', () => {
  const w = $('#inp').value;
  if (!w.trim()) return;
  $('#inp').value = stripAccentsKeepDiaeresis2(w);
  render();
});
$('#inp').addEventListener('input', () => {
  // live update, but debounce lightly
  clearTimeout(window.__t);
  window.__t = setTimeout(render, 120);
});

buildChips();
render();
